const odooUrl = '$env.ODOO_URL';
const db = '$env.ODOO_DB';
const uid = Number($env.ODOO_UID);
const password = '$env.ODOO_PASSWORD';

const modelName = query.trim();
const payload = {
  jsonrpc: '2.0',
  method: 'call',
  params: {
    service: 'object',
    method: 'execute',
    args: [db, uid, password, modelName, 'fields_get', [], ['string', 'type']]
  },
  id: Math.floor(Math.random() * 1000)
};

try {
  // Using n8n's native sandboxed request wrapper helper
  const resData = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl,
    headers: { 'Content-Type': 'application/json' },
    body: payload
  });

  if (resData.error) return JSON.stringify({ error: resData.error });

  const fields = resData.result || {};
  const cleanFields = {};
  for (const [key, value] of Object.entries(fields)) {
    cleanFields[key] = { label: value.string, type: value.type };
  }
  return JSON.stringify(cleanFields);
} catch (err) {
  return JSON.stringify({ error: err.message });
}

const odooUrl = '$env.ODOO_URL';
const db = '$env.ODOO_DB';
const uid = Number($env.ODOO_UID);
const password = '$env.ODOO_PASSWORD';

try {
  const input = JSON.parse(query);
  const model = input.model;
  const domain = input.domain || [];
  const fields = input.fields || ['id', 'display_name'];

  // THE SAFETY CAP: Default to a safe limit, absolute maximum ceiling of 80 records
  const userLimit = parseInt(input.limit, 10);
  const safeLimit = (!isNaN(userLimit) && userLimit > 0) ? Math.min(userLimit, 80) : 80;

  const payload = {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute',
      // Odoo search_read args: [db, uid, password, model, method, domain, fields, offset, limit]
      args: [db, uid, password, model, 'search_read', domain, fields, 0, safeLimit]
    },
    id: Math.floor(Math.random() * 1000)
  };

  const resData = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl,
    headers: { 'Content-Type': 'application/json' },
    body: payload
  });

  if (resData.error) return JSON.stringify({ error: resData.error });
  return JSON.stringify(resData.result || []);
} catch (err) {
  return JSON.stringify({ error: 'Execution failure: ' + err.message });
}

