const odooUrl = '$env.ODOO_URL';
const db = '$env.ODOO_DB';
const uid = Number($env.ODOO_UID);
const password = '$env.ODOO_PASSWORD';

try {
  const input = JSON.parse(query);
  const model = input.model;
  const domain = input.domain || [];
  const fields = input.fields || []; 
  const groupby = input.groupby || []; 

  // THE ACCURACY SHIELD: Force server-side sorting by group count descending
  // This ensures the absolute highest transaction rows are always pushed to the top slot
  const orderby = input.orderby || (groupby.length ? `${groupby}_count desc` : '');

  const payload = {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      service: 'object',
      method: 'execute',
      // Odoo RPC positional mapping: [db, uid, password, model, method, domain, fields, groupby, offset, limit, orderby]
      args: [db, uid, password, model, 'read_group', domain, fields, groupby, 0, 50, orderby]
    },
    id: Math.floor(Math.random() * 1000)
  };

  const resData = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl,
    headers: { 'Content-Type': 'application/json' },
    body: payload
  });

  if (resData.error) return JSON.stringify({ error: resData.error });
  return JSON.stringify(resData.result || []);
} catch (err) {
  return JSON.stringify({ error: 'Aggregation failure: ' + err.message });
}

try {
  // In the Custom Code Tool node, n8n passes the agent's input string as 'query'
  const expression = query || '';

  // SECURITY MANDATE: Strip all whitespace
  const sanitized = expression.replace(/\s+/g, '');

  // THE ACCURACY SHIELD: Only allow numbers, decimals, and basic math operators (+, -, *, /, (, ))
  if (!/^[0-9\+\-\*\/\.\(\)]+$/.test(sanitized)) {
    return JSON.stringify({ error: "Security Violation: Invalid mathematical expression character detected." });
  }

  // Execute the clean math string safely
  const result = Function(`"use strict"; return (${sanitized})`)();

  return JSON.stringify({ result: result });
} catch (err) {
  return JSON.stringify({ error: "Calculation failure: " + err.message });
}

try {
  // Parse the instructions coming from the AI agent
  const input = JSON.parse(query);
  const listA = input.datasetA || [];
  const listB = input.datasetB || [];
  const joinKey = input.joinKey;
  const metricA = input.metricA;
  const metricB = input.metricB;
  const operation = input.operation || 'ratio';
  const minMetricB = input.minMetricB !== undefined ? input.minMetricB : null;
  const limit = input.limit || 10;

  if (!joinKey || !metricA || !metricB) {
    return JSON.stringify({ error: "Missing required mapping parameters: joinKey, metricA, or metricB." });
  }

  // Optimize Dataset B into an ID map for fast O(N) lookup performance
  const mapB = {};
  listB.forEach(item => {
    // Handle Odoo's Many2one array formats [id, "Name"] or raw values smoothly
    const rawId = item[joinKey];
    const id = Array.isArray(rawId) ? rawId[0] : rawId;
    if (id !== undefined && id !== null && id !== false) {
      mapB[id] = item;
    }
  });

  const processedResults = [];

  // Join and execute custom metrics math logic
  listA.forEach(item => {
    const rawId = item[joinKey];
    const id = Array.isArray(rawId) ? rawId[0] : rawId;
    const nameStr = Array.isArray(rawId) ? rawId[1] : id;

    const match = mapB[id];
    if (match) {
      const valA = Number(item[metricA]) || 0;
      const valB = Number(match[metricB]) || 0;

      // Filter Constraint Safeguard (e.g., Ticket count must be greater than 1)
      if (minMetricB !== null && valB <= minMetricB) {
        return;
      }

      // Compute mathematical ratio safety shield (Anti-Division-by-Zero)
      let finalMetric = 0;
      if (valB !== 0) {
        finalMetric = valA / valB;
      }

      processedResults.push({
        company_name: nameStr,
        [metricA]: valA,
        [metricB]: valB,
        computed_ratio: Number(finalMetric.toFixed(2))
      });
    }
  });

  // Sort the resulting leaderboard descending based on the calculated metric
  processedResults.sort((a, b) => b.computed_ratio - a.computed_ratio);

  // Return exactly what the token cap limits allow
  return JSON.stringify(processedResults.slice(0, limit));
} catch (err) {
  return JSON.stringify({ error: "Data cruncher computation failure: " + err.message });
}

